/**
 * The server side of a machine's screen in an ejected project (ADR 0075 D4, D11), in
 * `<package>/block/`: copies of the runtime's `MsmFurnaceMenu` (as `MachineFurnaceMenu`) and
 * `MsmMachineResultSlot` (as `MachineResultSlot`), Minecraft 26.3, Mojang names. The generator's
 * tests compare every code line with the runtime's.
 *
 * @packageDocumentation
 */

/** The source of `MachineFurnaceMenu.java`, copied from the runtime's `MsmFurnaceMenu`. */
export function machineFurnaceMenuJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MsmFurnaceMenu.
package ${blockPackage};

import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.AbstractFurnaceMenu;
import net.minecraft.world.inventory.BlastFurnaceMenu;
import net.minecraft.world.inventory.ContainerData;
import net.minecraft.world.inventory.FurnaceMenu;
import net.minecraft.world.inventory.Slot;
import net.minecraft.world.inventory.SmokerMenu;
import net.minecraft.world.item.ItemStack;

/**
 * The server side of a machine's screen (ADR 0075 D4): a subclass of vanilla's {@link FurnaceMenu} (or
 * {@link Blast}, {@link Smoker} for {@code menu}), so the client opens the vanilla screen with no code of ours. On the
 * server {@link #canSmelt} asks the machine's own recipe types (shift-click into the input slot) and {@link #isFuel} is
 * false unless {@code power} is {@code fuel}; the output slot (index 2) is replaced by an {@link MachineResultSlot}
 * at the same place, keeping its index. The client predicts with vanilla's furnace rules and the server corrects it
 * (limit C10).
 */
public class MachineFurnaceMenu extends FurnaceMenu {
    private final MachineBlockEntity machine;

    public MachineFurnaceMenu(int id, Inventory inventory, MachineBlockEntity machine, ContainerData data) {
        super(id, inventory, machine, data);
        this.machine = machine;
        replaceResultSlot(this, inventory, machine);
    }

    /** The menu of {@code menu}'s kind for {@code machine}. */
    public static AbstractFurnaceMenu create(MachineSpec.Menu menu, int id, Inventory inventory,
            MachineBlockEntity machine, ContainerData data) {
        return switch (menu) {
            case FURNACE -> new MachineFurnaceMenu(id, inventory, machine, data);
            case BLAST_FURNACE -> new Blast(id, inventory, machine, data);
            case SMOKER -> new Smoker(id, inventory, machine, data);
        };
    }

    /** Puts an {@link MachineResultSlot} where vanilla's result slot is, keeping its index and position. */
    private static void replaceResultSlot(AbstractContainerMenu menu, Inventory inventory, MachineBlockEntity machine) {
        Slot old = menu.slots.get(AbstractFurnaceMenu.RESULT_SLOT);
        MachineResultSlot slot = new MachineResultSlot(inventory.player, machine, AbstractFurnaceMenu.RESULT_SLOT, old.x, old.y);
        slot.index = old.index;
        menu.slots.set(AbstractFurnaceMenu.RESULT_SLOT, slot);
    }

    @Override
    protected boolean canSmelt(ItemStack stack) {
        return machine != null ? machine.canProcess(stack) : super.canSmelt(stack);
    }

    @Override
    protected boolean isFuel(ItemStack stack) {
        return machine != null ? machine.isFuel(stack) : super.isFuel(stack);
    }

    /** The blast furnace screen ({@code menu: blast_furnace}). */
    public static class Blast extends BlastFurnaceMenu {
        private final MachineBlockEntity machine;

        public Blast(int id, Inventory inventory, MachineBlockEntity machine, ContainerData data) {
            super(id, inventory, machine, data);
            this.machine = machine;
            replaceResultSlot(this, inventory, machine);
        }

        @Override
        protected boolean canSmelt(ItemStack stack) {
            return machine != null ? machine.canProcess(stack) : super.canSmelt(stack);
        }

        @Override
        protected boolean isFuel(ItemStack stack) {
            return machine != null ? machine.isFuel(stack) : super.isFuel(stack);
        }
    }

    /** The smoker screen ({@code menu: smoker}). */
    public static class Smoker extends SmokerMenu {
        private final MachineBlockEntity machine;

        public Smoker(int id, Inventory inventory, MachineBlockEntity machine, ContainerData data) {
            super(id, inventory, machine, data);
            this.machine = machine;
            replaceResultSlot(this, inventory, machine);
        }

        @Override
        protected boolean canSmelt(ItemStack stack) {
            return machine != null ? machine.canProcess(stack) : super.canSmelt(stack);
        }

        @Override
        protected boolean isFuel(ItemStack stack) {
            return machine != null ? machine.isFuel(stack) : super.isFuel(stack);
        }
    }
}
`;
}

/** The source of `MachineResultSlot.java`, copied from the runtime's `MsmMachineResultSlot`. */
export function machineResultSlotJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MsmMachineResultSlot.
package ${blockPackage};

import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.FurnaceResultSlot;
import net.minecraft.world.item.ItemStack;

/**
 * The output slot of a machine's menu (ADR 0075 D4, D6): vanilla's {@link FurnaceResultSlot} (no placing, the crafted
 * item's own triggers), which pays experience only for an {@code AbstractFurnaceBlockEntity}; this one pays the
 * machine's stored experience to the taking player. {@link MachineFurnaceMenu} puts it at index 2 in place of vanilla's.
 */
public class MachineResultSlot extends FurnaceResultSlot {
    private final Player taker;
    private final MachineBlockEntity machine;

    public MachineResultSlot(Player player, MachineBlockEntity machine, int slot, int x, int y) {
        super(player, machine, slot, x, y);
        this.taker = player;
        this.machine = machine;
    }

    @Override
    protected void checkTakeAchievements(ItemStack stack) {
        super.checkTakeAchievements(stack);
        if (taker instanceof ServerPlayer player) {
            machine.payExperience(player);
        }
    }
}
`;
}
